"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisLogoCloudContent } from "./components/logo-cloud/content";
import View0 from "./components/logo-cloud/variants/01-marquee";
const variants = {"marquee":View0};
export type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "./components/logo-cloud/content";
export interface ArtemisLogoCloudProps { className?: string; variant?: "marquee"; /** The words on the logo cloud; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisLogoCloudContent>; }
export function ArtemisLogoCloud({ className, variant = "marquee", content }: ArtemisLogoCloudProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** One logo in the cloud. */
export interface ArtemisLogoCloudLogo {
  /**
   * The company's name, shown beside the icon. All layouts; carousel also lists every name for screen readers.
   * Keep names unique, since grid, columns and carousel tell logos apart by name.
   */
  name: string;
  /** A logo image shown in place of the icon and name, sized to the row; its alt text names the logo. All layouts. */
  image?: { src: string; alt: string };
  /** The icon beside the name. All layouts, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis logo cloud. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisLogoCloudContent {
  /** A small label over the headline. columns and carousel. */
  badge?: string;
  /** The heading. All layouts; marquee shows it as a small line over the logos. */
  headline: string;
  /** A line under or beside the headline. grid, columns and carousel. */
  subhead?: string;
  /**
   * The logos. All layouts: marquee scrolls them in one row, grid rolls them through eight cells, columns deals them
   * into four scrolling lanes and carousel turns them through two or four slots. Twelve look best; grid needs more
   * than eight to roll.
   */
  logos: ArtemisLogoCloudLogo[];
}

"use client";
// @zeus-internal
import { Aperture, Box, Circle, Command, Gem, Hexagon, Octagon, Triangle } from "lucide-react";
import { motion, useAnimationFrame, useMotionValue, useReducedMotion } from "motion/react";
import { type ComponentType, useEffect, useRef } from "react";
import type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "../content";
const defaultLogos: ArtemisLogoCloudLogo[] = [
    { name: "Workspace" },
    { name: "Group A" },
    { name: "Group B" },
    { name: "Group C" },
    { name: "Group D" },
    { name: "Group E" },
    { name: "Group F" },
    { name: "Group G" },
];
const DEFAULT = {
    headline: "Trusted by teams shipping with Artemis",
    logos: defaultLogos,
} satisfies ArtemisLogoCloudContent;
/** The icon for each slot, for logos that come without one. */
const ICONS = [Hexagon, Triangle, Aperture, Box, Gem, Command, Octagon, Circle];
const SPEED = 26;
const VIEW_INSET = 0.1;
export default function LogoCloudMarquee({ content }: { content?: Partial<ArtemisLogoCloudContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const track = [...copy.logos, ...copy.logos];
    const x = useMotionValue(0);
    const sectionRef = useRef<HTMLElement>(null);
    const trackRef = useRef<HTMLDivElement>(null);
    const hoveredRef = useRef(false);
    const visibleRef = useRef(false);
    const reduceMotion = useReducedMotion();
    useEffect(() => {
        const section = sectionRef.current;
        if (!section)
            return;
        const observer = new IntersectionObserver((entries) => {
            for (const entry of entries)
                visibleRef.current = entry.isIntersecting;
        }, { rootMargin: `-${VIEW_INSET * 100}% 0px -${VIEW_INSET * 100}% 0px` });
        observer.observe(section);
        return () => observer.disconnect();
    }, []);
    useAnimationFrame((_, delta) => {
        const track = trackRef.current;
        if (!track || reduceMotion || !visibleRef.current || hoveredRef.current)
            return;
        const half = track.offsetWidth / 2;
        if (half <= 0)
            return;
        let next = x.get() - (SPEED * delta) / 1000;
        if (next <= -half)
            next += half;
        x.set(next);
    });
    return (<div className="art:w-full">
      <section ref={sectionRef} className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <p className="art:text-center art:font-medium art:text-muted-foreground art:text-sm">{copy.headline}</p>
          <div className="art:relative art:mt-8 art:overflow-hidden art:[mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]" onMouseEnter={() => {
            hoveredRef.current = true;
        }} onMouseLeave={() => {
            hoveredRef.current = false;
        }}>
            <div className="art:flex art:w-max">
              <motion.div ref={trackRef} className="art:flex art:w-max art:items-center art:gap-12 art:pr-12" style={{ x }}>
                {track.map((logo, index) => {
            const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = logo.icon ?? ICONS[(index % copy.logos.length) % ICONS.length];
            return (<span key={index} className="art:flex art:shrink-0 art:items-center art:gap-2 art:text-muted-foreground/70 art:transition-colors art:hover:text-foreground">
                      {logo.image ? <img src={logo.image.src} alt={logo.image.alt} className="art:h-7 art:w-auto art:max-w-full art:object-contain"/> : <>
                      <Icon className="art:size-5" strokeWidth={1.75}/>
                      <span className="art:font-semibold art:text-lg art:tracking-tight">{logo.name}</span>
                      </>}
                    </span>);
        })}
              </motion.div>
            </div>
          </div>
        </div>
      </section>
    </div>);
}
